using System;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PyramidalAnomalyOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/PyramidalAnomaly Omen Data")]
public class PyramidalAnomalyOmenData : OnEnemyOverCorruptedOmenData
{
	[Header("PyramidalAnomalyOmenData")]
	[SerializeField]
	private SoulHeat soulHeat;

	[SerializeField]
	private PurifiedLightningAction purifiedLightningAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(GameObject overCorruptedEnemy)
		{
			int soulHeatCounter = soulHeat.SoulHeatCounter;
			if (soulHeatCounter > 0)
			{
				Action onEachPurifyAction = null;
				PlayerEffects playerEffects = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();
				if (playerEffects.IsFlammableChakramActive())
				{
					onEachPurifyAction = delegate
					{
						playerEffects.IsFlammableChakramActiveApplyRelief(overCorruptedEnemy);
					};
				}
				purifiedLightningAction.SingleTargetCastDefaultBeforeMainActionCoroutine(overCorruptedEnemy, soulHeatCounter, ActionValue, null, onEachPurifyAction, delegate
				{
					omenInstance.EnqueueOmenFeedbackAndPlay();
				});
			}
		};
		SetMiscOmensHandlerOmenAction();
	}

	public override string OmenConvertedDescription()
	{
		return GetOverCorruptChantDescription() + base.localizationManager.GetLocalizedWhereXTimes(GetLocalizedOmenLogicDescription().RemoveLast(), y: false, base.localizationManager.GetLocalizedString("Sandstorm_D")) + "\n" + GetOmenRawLocalizedDescription();
	}
}
